async function createBoard(kind){if(!state.user)return showAuth(setupNeeded?'setup':'login');try{const b=await post('/boards',{title:titles[kind]});await openBoard(b.id);const objects=template(kind);if(objects.length){await commit(objects.map(o=>({id:o.id,object:o})),false);fit()}await loadBoards()}catch(e){toast(e.message)}}
