function subscribe(id){state.source=new EventSource('/api/boards/'+id+'/events?client='+encodeURIComponent(state.client));state.source.onopen=()=>{state.online=true;updateSave()};state.source.onerror=()=>{state.online=false;updateSave()};state.source.onmessage=async e=>{if(state.board?.id!==id)return;const d=JSON.parse(e.data);if(d.type==='patch'&&d.client!==state.client){apply(d.changes);render();}if(d.type==='resync'){try{const version=state.changeVersion,snapshot=await api('/boards/'+id);if(state.board?.id===id){state.comments=snapshot.comments;if(version===state.changeVersion&&!state.dirty&&!drag&&!editing){state.objects=new Map(snapshot.objects.map(o=>[o.id,o]));render()}renderComments()}}catch{}}if(d.type==='presence'){$('#presence').innerHTML=d.users.map(u=>`<span class="avatar" title="${esc(u.name)}${u.id===state.user.id?' (você)':''}">${esc(initials(u.name))}</span>`).join('')}if(d.type==='title'){state.board.title=d.title;$('#boardTitle').value=d.title;$('#crumb').textContent=d.title}if(d.type==='comment'){if(!state.comments.some(c=>c.id===d.comment.id))state.comments.push(d.comment);renderComments()}if(d.type==='cursor'&&d.client!==state.client){let el=document.getElementById('cursor-'+d.user.id);if(!el){el=document.createElement('div');el.id='cursor-'+d.user.id;el.className='cursor';$('#cursors').append(el)}el.innerHTML='↖<small>'+esc(d.user.name)+'</small>';el.style.left=d.x+'px';el.style.top=d.y+'px';el.hidden=false;clearTimeout(el._timer);el._timer=setTimeout(()=>el.remove(),5000)}if(d.type==='deleted'){state.dirty=0;await dashboard();toast('Este quadro foi excluído.')}}}
