  if(ids.length){$('#fillColor').value=safeColor(state.objects.get(ids[0]).color);if(state.objects.get(ids[0]).type==='text')$('#fillColor').value=textFormat(state.objects.get(ids[0])).color;$('#selectionSwatch').style.background=$('#fillColor').value}for(const id of ['selectionColor','deleteBtn'])$('#'+id).disabled=locked;$('#frontBtn').disabled=locked||!ids.some(id=>!['frame','line','pen'].includes(state.objects.get(id).type));
