  $('#objects').innerHTML=[...state.objects.values()].filter(o=>!['line','pen'].includes(o.type)).sort((a,b)=>(a.type==='frame'?-1:0)-(b.type==='frame'?-1:0)||(a.z||0)-(b.z||0)).map(o=>`<div id="obj-${o.id}" data-id="${o.id}" data-group="${esc(o.groupId||'')}" class="object ${o.type} ${elementLocked(state.objects,o.id)?'locked':''} ${selected.has(o.id)?'selected':''}" style="left:${o.x}px;top:${o.y}px;width:${o.w}px;height:${o.h}px;background:${safeColor(o.color)};--object-color:${safeColor(o.color)};${TEXT_TYPES.includes(o.type)?textCss(o)+'align-items:'+({top:'flex-start',middle:'center',bottom:'flex-end'}[textFormat(o).vertical]||'flex-start')+';':''}">${o.type==='image'?`<img src="${esc(o.src)}" alt="Imagem do quadro">`:`<span class="label">${esc(o.text||'')}</span>`}${elementLocked(state.objects,o.id)?'<span class="object-lock" aria-label="Elemento bloqueado">🔒</span>':''}${connectionHandles(o)}${selected.has(o.id)&&single?resizeHandles():''}</div>`).join('');
